[5481] = { en = "Gordo's Task", tier = 1,
  t = "De taak van Gordo",
  d = "Meester wil onkruid. Wij hebben grote handen en zijn niet goed in plukken. Jij helpt ons, en wij doen jou geen pijn. Wij hebben Gloom Weed nodig. Veel onkruid hier in de buurt en bij de weg.$b$bAls jij Gloom Weed hebt, breng jij het naar meester Holland op het kerkhof van Brill.$b",
  o = "Verzamel 3 Gloom Weed en breng ze naar Junior Apothecary Holland op het kerkhof van Brill.",
  p = "Waar is die nutteloze abominatie? Of je hebt wat ik nodig heb, of je kunt beter naar buiten gaan om het te zoeken.",
  c = "Wat is dit? Gloom Weed?! Ik heb geen Gloom Weed nodig! Die domme klomp vlees plukt daar madeliefjes. En alleen de Lady weet hoeveel sukkels zoals jij hij zover krijgt om hetzelfde te doen. Niet persoonlijk bedoeld.$b$bNou goed, je bent nu hier, en dat is het belangrijkste. Ik ga het niet aan die abominatie proberen uit te leggen. Dus verzamel jij wat ik echt nodig heb... Doom Weed!",
  g = { {"onkruid", "weeds"}, {"plukken", "to pick"}, {"in de buurt", "around here, nearby"}, {"kerkhof", "graveyard"}, {"nutteloze", "useless (nutteloos)"}, {"abominatie", "abomination"}, {"klomp vlees", "lump of flesh"}, {"madeliefjes", "daisies (madeliefje)"}, {"sukkels", "dupes, suckers (sukkel)"}, {"Niet persoonlijk bedoeld", "no offense"}, {"uit te leggen", "to explain (uitleggen)"} },
},

[367] = { en = "A New Plague", tier = 1,
  t = "Een nieuwe pest",
  d = "Lady Sylvanas heeft de Royal Apothecary Society om hulp gevraagd. De Dark Lady gelooft dat onze kennis, samen met de nieuwe magie, de sleutel is tot de ondergang van Arthas. Ze heeft ons uitgedaagd om een nieuwe pest te maken. Een pest die dodelijker is dan elke ziekte op Azeroth. Deze nieuwe ziekte maakt het Scourge-leger van Arthas kapot.$b$bVolgens mijn onderzoek kan het bloed van dieren de sleutel zijn. Breng me 5 Vials of Darkhound Blood, zodat ik mijn theorie kan testen.",
  o = "Apothecary Johaan in het dorp Brill wil dat je 5 Vials of Darkhound Blood verzamelt.",
  p = "Heb je de 5 Vials of Darkhound Blood al, $N? De tijd gaat snel!",
  c = "Je hebt het goed gedaan, $N. Ik dank je voor je moeite.",
  g = { {"pest", "plague"}, {"kennis", "knowledge"}, {"sleutel", "key"}, {"ondergang", "downfall, demise"}, {"uitgedaagd", "challenged (uitdagen)"}, {"dodelijker", "deadlier (dodelijk)"}, {"ziekte", "disease, ailment"}, {"onderzoek", "research, studies"}, {"moeite", "effort"} },
},

[404] = { en = "A Putrid Task", tier = 1,
  t = "Een smerige taak",
  d = "De Scourge is langzaam Tirisfal Glades binnengekomen. Ze zitten nu overal in het gebied ten westen van Brill, bij de oude brug.$B$BGa daarheen en sla de rottende doden en de verscheurde lijken terug. Gooi hun botten alle kanten op en breng hun Putrid Claws mee. Dan krijg je een beloning van de Deathguards.",
  o = "Breng 7 Putrid Claws naar Deathguard Dillinger in Brill.",
  p = "Heb je de taak gedaan die ik je gegeven heb? Heb je die Putrid Claws?",
  c = "Goed gedaan. Jammer dat ik er niet bij was. Ik had graag gezien hoe je die ondoden tot rottende moes sloeg!",
  g = { {"smerige", "filthy, nasty (smerig)"}, {"binnengekomen", "come in (binnenkomen)"}, {"gebied", "area"}, {"rottende", "rotting (rotten)"}, {"verscheurde", "ravaged, torn (verscheuren)"}, {"lijken", "corpses (lijk)"}, {"botten", "bones (bot)"}, {"alle kanten op", "in all directions"}, {"beloning", "reward"}, {"ondoden", "undead (ondode)"}, {"moes", "pulp, mush"} },
},

[5482] = { en = "Doom Weed", tier = 1,
  t = "Doom Weed",
  d = "Nu snap je mijn probleem, $N. Dat ding plukt daar het verkeerde onkruid! Als je me helpt, wordt het de moeite waard. Breng me genoeg Doom Weed, en je krijgt een goede beloning.$B$BVoor zover ik weet, groeit het graag tussen de planten bij het massagraf, ten noorden van het kerkhof van Brill. Schiet op, en let op de gnolls in dat gebied.",
  o = "Verzamel 10 Doom Weed en breng ze terug naar Junior Apothecary Holland.",
  p = "Dit moet wel goed zijn. Je hebt toch alle Doom Weed die ik nodig heb?",
  c = "Ah, mijn Doom Weed. Uitstekend!$B$B<Junior Apothecary Holland wrijft gretig in zijn handen.>$B$BDit komt heel goed van pas. Je hebt mij, eh, de Lady, vandaag goed geholpen, $N. Zoals beloofd: hier is de beloning die je verdient.",
  g = { {"snap", "understand (snappen)"}, {"verkeerde", "wrong (verkeerd)"}, {"de moeite waard", "worth your while"}, {"Voor zover ik weet", "as far as I know"}, {"massagraf", "mass grave"}, {"Schiet op", "hurry up (opschieten)"}, {"let op", "watch out for (letten op)"}, {"wrijft", "rubs (wrijven)"}, {"gretig", "greedily, eagerly"}, {"komt ... van pas", "comes in handy (van pas komen)"}, {"verdient", "deserve (verdienen)"} },
},

[361] = { en = "A Letter Undelivered", tier = 1,
  t = "Een brief die nooit aankwam",
  d = "Dit is een brief van Thurman, de oudste zoon van Gregor Agamand. Hij is voor een zekere Yvette Farthing. Maar het lijkt erop dat ze hem nooit gekregen heeft...",
  o = "Zoek Yvette Farthing en geef haar de brief van Thurman Agamand.",
  p = "Ja?",
  c = "O... mijn arme Thurman! Ik smeekte hem om met mij en mijn vader weg te gaan uit Agamand Mills. Maar hij was te trouw aan zijn familie! En ik wist het! Ik wist gewoon dat Brand hem kwaad wilde doen!! O, die vervloekte Pest, en die Scourge!$B$B<Yvettes gezicht wordt glad en koud.>$B$BMaar spijt is voor de zwakken. Als Forsaken heb ik nieuwe doelen, en liefde hoort daar niet bij. Ik wil je bedanken voor deze brief, want ik vroeg me af wat er met mijn oude liefde gebeurd was.$B$BMaar dat leven is voorbij. Voor altijd.",
  g = { {"aankwam", "arrived (aankomen)"}, {"oudste", "eldest (oud)"}, {"een zekere", "a certain"}, {"het lijkt erop", "it seems"}, {"smeekte", "begged (smeken)"}, {"trouw", "loyal"}, {"kwaad wilde doen", "meant harm (kwaad doen)"}, {"vervloekte", "cursed (vervloekt)"}, {"glad", "smooth"}, {"spijt", "regret"}, {"zwakken", "the weak (zwak)"}, {"doelen", "goals (doel)"}, {"voorbij", "over, past"} },
},

[365] = { en = "Fields of Grief", tier = 1,
  t = "Velden van verdriet",
  d = "Wat hebben we hier? Je ziet eruit als een beginnende $c. Wil je jezelf bewijzen aan de Dark Lady? Dan moet je de wegen van de Forsaken leren.$b$bIn het westen ligt een boerderij. De mensen zitten overal op dat land, als schimmel op een rottend lijk. En nog erger: de Scarlet Crusade patrouilleert vlakbij, vanuit hun toren. Geef dat tuig een lesje en steel 10 van hun kostbare pompoenen.$b$bAls je er 10 hebt, breng ze dan naar Apothecary Johaan in Brill.",
  o = "Steel 10 pompoenen van de boerderij in het westen, net ten noorden van Deathknell. Breng ze naar Apothecary Johaan in Brill.",
  p = "Deathguard Simmer heeft laten weten dat je me wat hard nodige ingrediënten komt brengen. Heb je al 10 pompoenen, $N?",
  c = "Je hebt je opdracht goed uitgevoerd, jonge $c. Je bent heel waardevol voor het leger van de Dark Lady.",
  g = { {"verdriet", "grief, sorrow"}, {"beginnende", "beginning, fledgling (beginnen)"}, {"bewijzen", "to prove"}, {"boerderij", "farm"}, {"schimmel", "mold"}, {"patrouilleert", "patrols (patrouilleren)"}, {"tuig", "scum, riffraff"}, {"een lesje", "a lesson"}, {"kostbare", "precious (kostbaar)"}, {"pompoenen", "pumpkins (pompoen)"}, {"laten weten", "sent word, let know"}, {"uitgevoerd", "carried out (uitvoeren)"}, {"waardevol", "valuable, an asset"} },
},

[374] = { en = "Proof of Demise", tier = 1,
  t = "Bewijs van hun dood",
  d = "Executor Zygand vertelt me dat je Scarlet Crusaders hebt gedood. Tirisfal Glades zit vol met ze.$b$bVarimathras, de luitenant van de Dark Lady, zorgt zelf dat het tuig van Azeroth, het mensenras, helemaal wordt weggevaagd. Hier in Tirisfal Glades hebben we last van een heel vervelende soort mensen: de Scarlet Crusade.$b$bGa op pad en val de Scarlet Crusade aan, $c. Breng me 10 Scarlet Insignia Rings, als bewijs dat je trouw bent aan Varimathras en de Dark Lady.",
  o = "Breng 10 Scarlet Insignia Rings naar Deathguard Burgess in Brill.",
  p = "Heb je al 10 Scarlet Insignia Rings, $c?",
  c = "Varimathras zou trots zijn. Je dient je leiders goed, $C.",
  g = { {"bewijs", "proof"}, {"zit vol met", "is crawling with"}, {"luitenant", "lieutenant"}, {"mensenras", "human race"}, {"weggevaagd", "wiped out (wegvagen)"}, {"last van", "trouble with"}, {"vervelende", "annoying (vervelend)"}, {"soort", "kind, breed"}, {"Ga op pad", "set out, venture forth"}, {"dient", "serve (dienen)"} },
},

[407] = { en = "Fields of Grief", tier = 1,
  t = "Velden van verdriet",
  d = "Onschuldige pompoenen, toch? Zo lijkt het tenminste. We willen de aanvallen van Arthas uit het noorden verslaan, en ook de mensenplaag uit het zuiden. Dan moeten we de volle kracht van ons geschenk gaan zien: de ondood.$b$bMet een beetje slimheid wordt een simpele pompoen een werktuig voor onze Dark Lady. Deze pompoen zit vol met mijn nieuwste formule. Het wordt echt een lekkernij.$b$bWeer is er een Scarlet Zealot gevangen. Hij zit in de kelder van de Gallow's End Tavern. Breng deze pompoen naar die dwaas.",
  o = "Breng de Laced Pumpkin naar de Captured Scarlet Zealot. Hij zit gevangen in de kelder van de Gallow's End Tavern.",
  p = "Blijf weg, vies en onheilig wezen! Moge het Licht mij beschermen! De Scarlet Crusade zal Azeroth bevrijden van jouw. . .$b$b. . .o, wacht. Is dat eten voor mij? Ik heb zo'n honger. . .",
  c = "Bij het Licht! Eindelijk eten! Lekkere, lekkere pompoen. . . .",
  g = { {"Onschuldige", "harmless, innocent (onschuldig)"}, {"tenminste", "at least"}, {"verslaan", "to defeat"}, {"mensenplaag", "human infestation"}, {"geschenk", "gift"}, {"ondood", "undeath"}, {"slimheid", "cleverness, ingenuity"}, {"werktuig", "tool, instrument"}, {"lekkernij", "treat"}, {"kelder", "cellar"}, {"dwaas", "fool"}, {"onheilig", "unholy"}, {"Moge", "may (mogen)"}, {"bevrijden", "to free, to rid"} },
},

[358] = { en = "Graverobbers", tier = 1,
  t = "Grafrovers",
  d = "De Mass Graves liggen ten zuidwesten van Garren's Haunt, in het noorden. Ze zijn gemaakt voor het... indrukwekkende... aantal doden in Tirisfal, toen de Pest voor het eerst kwam.$B$BDe lichamen in deze graven zijn tot nu toe niet ondood geworden. Maar nu stuurt de Scourge Rot Hide Gnolls om de lijken te verzamelen. Ze gebruiken die om hun legers sterker te maken. Dat mag niet gebeuren!$B$BJe taak heeft twee delen. Dood de Rot Hides bij de Mass Grave en Garren's Haunt. En haal bij hen de Embalming Ichor, die hen leven geeft.",
  o = "Dood Rot Hide Graverobbers en Rot Hide Mongrels.$B$BBreng 8 Embalming Ichors naar Magistrate Sevren in Brill.",
  p = "Is je taak klaar? Heb je die hondachtige wezens vernietigd en hun vocht eruit gehaald?",
  c = "Heel knap gedaan, $N. De Scourge vergist zich als ze denkt dat ze die lijken tegen ons kan gebruiken. Het vocht dat je bij de Rot Hide-slaven hebt verzameld, wordt onderzocht door onze apothekers. Misschien heeft het geheimen die we tegen ze kunnen gebruiken.$B$BZoals ik al zei: goed gedaan. Maar onze strijd gaat door, en deze oorlog geeft je vast nog meer kansen om jezelf te bewijzen aan de Forsaken.",
  g = { {"Grafrovers", "graverobbers (grafrover)"}, {"indrukwekkende", "impressive (indrukwekkend)"}, {"lichamen", "bodies (lichaam)"}, {"graven", "graves (graf)"}, {"tot nu toe", "so far"}, {"hondachtige", "dog-like (hondachtig)"}, {"vocht", "fluid"}, {"knap", "skillfully, clever"}, {"vergist zich", "is mistaken (zich vergissen)"}, {"onderzocht", "studied (onderzoeken)"}, {"apothekers", "apothecaries (apotheker)"}, {"geheimen", "secrets (geheim)"}, {"strijd", "struggle, fight"} },
},

[366] = { en = "Return the Book", tier = 1,
  t = "Breng het boek terug",
  d = "Lang geleden waren Gunther en ik vrienden, samen met Thule Ravenclaw, die nu een Scourge Necromancer is. We waren studenten bij de Kirin Tor, een groep magiërs in Dalaran.$B$BGunther en ik stierven allebei aan de Pest. Ik dacht dat hij dood bleef, of dat hij werd opgewekt in het leger van de Lich King. Het is goed om te weten dat hij vrij is.$B$BWe moeten hem bij ons hebben. Ik heb een spreuk op zijn boek gelegd. Als hij het ziet, laat het hem zien dat ik ook vrij ben van de Lich King. Als hij dat weet, hoop ik dat hij zich bij ons aansluit.",
  o = "Breng Gunther's Spellbook terug naar hem, op het eiland Gunther's Retreat.",
  p = "Je meesters zijn dwazen dat ze je hierheen sturen. Ik zal nooit meer een slaaf van de Scourge zijn!",
  c = "Mijn boek?!? Dus jij was de dief die het gestolen heeft!$B$BMaar... wat is deze nieuwe betovering erop... Bethor? Is hij in Lordaeron?$B$BAls hij nog bestaat, dan is hij misschien ook ontsnapt uit de greep van de Lich King...",
  g = { {"magiërs", "mages (magiër)"}, {"stierven", "died (sterven)"}, {"opgewekt", "raised (opwekken)"}, {"spreuk", "spell"}, {"zich bij ons aansluit", "joins us (zich aansluiten)"}, {"dwazen", "fools (dwaas)"}, {"slaaf", "slave"}, {"gestolen", "stolen (stelen)"}, {"betovering", "enchantment"}, {"ontsnapt", "escaped (ontsnappen)"}, {"greep", "grasp, grip"} },
},

[375] = { en = "The Chill of Death", tier = 1,
  t = "De kou van de dood",
  d = "Het is nu zo koud. De Pest van de ondood kruipt door mijn aderen als een ijskoude slang. Snel kom ik in de geestloze toestand. Maar geen noodlot houdt me tegen om onze Dark Lady te dienen. Toen de oproep kwam, naaide ik lijkzakken voor de gevallen soldaten van het machtige leger van Sylvanas.$b$bNu trillen mijn handen van de kou. Als je me vijf Duskbat Pelts en wat Coarse Thread brengt, kan ik een deken voor mezelf naaien. Help me, $N, zodat ik de zaak kan blijven dienen.",
  o = "Breng vijf Duskbat Pelts en wat Coarse Thread naar Gretchen Dedmar in Brill.",
  p = "Heb je de vijf Duskbat Pelts en wat Coarse Thread al, $N?",
  c = "Ik waardeer je moeite, $N. Moge Sylvanas op een dag je moed zien. . . .",
  g = { {"kou", "cold, chill"}, {"kruipt", "crawls (kruipen)"}, {"aderen", "veins (ader)"}, {"ijskoude", "icy (ijskoud)"}, {"geestloze", "mindless (geestloos)"}, {"toestand", "state"}, {"noodlot", "fate, doom"}, {"houdt me tegen", "stops me (tegenhouden)"}, {"oproep", "call"}, {"naaide", "sewed (naaien)"}, {"lijkzakken", "body bags (lijkzak)"}, {"trillen", "shake, tremble"}, {"deken", "blanket"}, {"zaak", "cause"}, {"waardeer", "appreciate (waarderen)"} },
},

[405] = { en = "The Prodigal Lich", tier = 1,
  t = "De verloren lich",
  d = "Bethor Iceshard is een belangrijke en machtige magiër in de Undercity, in het zuiden. Hij geeft me het bevel om hem een agent te sturen, iemand die zich al heeft bewezen tegen de Scourge. Jij, $N, wordt die agent.$B$BGeef deze bevelen aan Bethor. Hij vertelt je dan wat je missie is. Ik weet de details niet. Maar het gaat om het werven van een lich die zijn eigen weg gaat. En het wordt gevaarlijk.$B$BBereid je dus voor, $C. Je mag niet falen.$B$BJe vindt Bethor in het Magic Quarter van de Undercity.",
  o = "Geef Sevren's Orders aan Bethor Iceshard in de Undercity.",
  p = "Gegroet. Of je weet niet wie ik ben, of je zaak met mij is dringend.$B$BWant als geen van beide waar was, dan zou je niet zo dwaas zijn om mij te storen...",
  c = "Ah, jij bent de agent van Magistrate Sevren. Dan is je zaak met mij inderdaad heel belangrijk.$B$BIk vertrouw erop dat Sevren iemand heeft gevonden die geschikt is voor mijn taak... maar dat zullen we zien.",
  g = { {"verloren", "prodigal, lost (verliezen)"}, {"bevel", "order, command"}, {"werven", "to recruit"}, {"Bereid je ... voor", "ready yourself (zich voorbereiden)"}, {"falen", "to fail"}, {"Gegroet", "greetings"}, {"zaak", "business, matter"}, {"dringend", "urgent"}, {"geen van beide", "neither"}, {"storen", "to disturb"}, {"inderdaad", "indeed"}, {"geschikt", "suitable"} },
},

[426] = { en = "The Mills Overrun", tier = 1,
  t = "De molens overrompeld",
  d = "De Scourge probeert een basis te maken bij de Agamand Mills. Als dat lukt, kunnen ze van daaruit meer aanvallen in Tirisfal doen.$B$BDe bevelen zijn gegeven. De Scourge in de molens moet vernietigd worden.$B$BGa naar de molens. Verzamel Notched Ribs van Rattlecage Soldiers en Cracked Skull Soldiers, en Blackened Skulls van Darkeye Bonecasters.$B$BZo kom je bij de molens: volg de weg naar het westen. Ga over de brug en neem dan de volgende afslag naar het noorden. Blijf daarna naar het noorden gaan. Als je windmolens ziet, begint het gevecht.",
  o = "Verzamel 5 Notched Ribs en 3 Blackened Skulls. Ga dan terug naar Deathguard Dillinger in Brill.",
  p = "Onze gevechten met de Scourge gaan door, $N. Doe jouw deel en jaag die vervloekte, geestloze ondoden terug naar de Plaguelands!",
  c = "We merken je inzet in de oorlog, $N. Ik ga je niet bedanken voor wat nodig is. Maar de Deathguards van Tirisfal zullen je naam onthouden.",
  g = { {"molens", "mills (molen)"}, {"overrompeld", "overrun (overrompelen)"}, {"lukt", "succeeds (lukken)"}, {"van daaruit", "from there"}, {"vernietigd", "destroyed (vernietigen)"}, {"afslag", "turn, fork"}, {"windmolens", "windmills (windmolen)"}, {"gevecht", "battle, fight"}, {"jaag", "drive, chase (jagen)"}, {"inzet", "effort, commitment"}, {"onthouden", "to remember"} },
},

[427] = { en = "At War With The Scarlet Crusade", tier = 1,
  t = "In oorlog met de Scarlet Crusade",
  d = "De documenten van Executor Arren zijn precies de doorbraak die we nodig hadden in onze strijd met die ellendige Scarlet Crusade. Nu weten we precies waar ze overal zitten in Tirisfal Glades.$b$bMaar de Deathguard heeft grotere zorgen. Het leger van de Lich King wordt elke nacht groter. We hebben iemand met 'initiatief' nodig, zoals jij, om de Scarlet Crusade het graf in te jagen.$b$bBewijs dat je de Dark Lady kunt dienen. Reis naar het westen, naar de toren voorbij de Solliden Farmstead, en dood 10 Scarlet Warriors.",
  o = "Executor Zygand van Brill wil dat je 10 Scarlet Warriors doodt.",
  p = "Wil je jezelf bewijzen aan de Dark Lady? Dood dan 10 Scarlet Warriors, $c.",
  c = "Uitstekend, $c. Het is duidelijk: jij kunt goed vechten.",
  g = { {"doorbraak", "break, breakthrough"}, {"ellendige", "wretched (ellendig)"}, {"zorgen", "concerns, worries (zorg)"}, {"initiatief", "initiative"}, {"het graf in te jagen", "to drive into the grave"}, {"voorbij", "past, beyond"}, {"Uitstekend", "excellent"}, {"duidelijk", "clear, undeniable"} },
