[359] = { en = "Forsaken Duties", tier = 1,
  t = "Plichten van de Forsaken",
  d = "Ik heb een nieuw verslag nodig van onze Deathguard-post in het oosten.$B$BIk moet weten of er meer Scourge-troepen langs The Bulwark zijn geglipt, Tirisfal in. We moeten de grens met de Plaguelands goed blijven bewaken. De Scourge mag hier niet steviger voet aan de grond krijgen!$B$BReis naar het zuiden over de weg. Ga bij de splitsing naar het oosten, naar de post. Praat met Deathguard Linnea. Zij heeft de informatie die ik nodig heb.",
  o = "Praat met Deathguard Linnea.",
  c = "Wil Magistrate Sevren een verslag? Goed dan. De verdedigers bij The Bulwark houden het grootste deel van de Scourge tegen. Maar soms glippen er een paar doorheen.$B$BWe hebben ten oosten van deze post af en toe Scourge gezien, vooral rond de Balnir Farmstead.",
  g = { {"Plichten", "duties (plicht)"}, {"verslag", "report"}, {"troepen", "forces, troops (troep)"}, {"geglipt", "slipped (glippen)"}, {"grens", "border"}, {"bewaken", "to guard"}, {"voet aan de grond krijgen", "to get a foothold"}, {"splitsing", "fork (in a road)"}, {"verdedigers", "defenders (verdediger)"}, {"grootste deel", "majority"}, {"af en toe", "now and then, sporadic"} },
},

[360] = { en = "Return to the Magistrate", tier = 1,
  t = "Terug naar de magistraat",
  d = "Ga nu terug naar Magistrate Sevren met de informatie die ik je gaf. Hij wil die zo snel mogelijk hebben, dus wees snel.$B$BEn zie je onderweg Scourge? Dood ze dan. We kunnen ze niet zomaar door ons land laten zwerven.",
  o = "Ga terug naar Magistrate Sevren in Brill.",
  c = "Het is zorgelijk dat de Scourge langs de Bulwark glipt. De Lich King en zijn dienaren stoppen nooit met hun aanvallen.$B$BMaar we geven niet op. Hij krijgt ons niet nog een keer!",
  g = { {"magistraat", "magistrate"}, {"zo snel mogelijk", "as soon as possible"}, {"onderweg", "on the way"}, {"zomaar", "just like that, unchallenged"}, {"zwerven", "to wander"}, {"zorgelijk", "troubling, worrying"}, {"dienaren", "minions, servants (dienaar)"}, {"geven ... op", "give up (opgeven)"} },
