[368] = { en = "A New Plague", tier = 1,
  t = "Een nieuwe pest",
  d = "Terwijl jij stalen voor me verzamelde, deed ik experimenten. Daardoor begreep ik dat ik meer ingrediënten nodig heb, zodat deze nieuwe ziekte zich goed kan verspreiden. Een arm slachtoffer vergiftigen is kinderspel. Een hele wereld besmetten is iets moeilijker.$b$bIk heb 5 Vile Fin Scales nodig van de murlocs hier in de buurt. Je vindt die wezens langs de kust in het noorden of in het westen.",
