[370] = { en = "At War With The Scarlet Crusade", tier = 1,
  t = "In oorlog met de Scarlet Crusade",
  d = "In de strategische documenten van Executor Arren staat alles wat we nodig hebben om de mensenplaag van dit land te vegen. Volgens die informatie heeft de Scarlet Crusade Captain Perrine en een brigade naar de verwoeste toren ten zuidwesten van Brill gestuurd.$b$bDood Perrine, samen met 3 Zealots en 3 Missionaries, en kom dan bij me terug.",
  o = "Executor Zygand in Brill wil dat je Captain Perrine, 3 Scarlet Zealots en 3 Scarlet Missionaries doodt.",
  p = "Jonge $c, je moet hier in Brill je tijd niet verspillen, want je volk heeft je nodig in de strijd voor hun zaak. Pak nu je wapens en reis naar het zuidwesten, naar de verwoeste toren. Dood daar Captain Perrine, samen met 3 Scarlet Zealots en 3 Scarlet Missionaries. We drijven de Scarlet Crusade als vee naar hun ondergang.",
  c = "De dood van Captain Perrine zal de Dark Lady zeker blij maken. Je hebt je plicht goed gedaan, $C.",
  g = { {"strategische", "strategic (strategisch)"}, {"vegen", "to sweep, to wipe"}, {"Volgens", "according to"}, {"verwoeste", "ruined (verwoest)"}, {"verspillen", "to waste"}, {"volk", "people"}, {"wapens", "arms, weapons (wapen)"}, {"drijven", "drive, herd"}, {"vee", "cattle"}, {"plicht", "duty"} },
},

[355] = { en = "Speak with Sevren", tier = 1,
  t = "Praat met Sevren",
  d = "Je hebt me de resten van de Agamands gegeven. Nu heb ik mijn wraak. Maar de Agamand Mills zijn een gevaar voor alle Forsaken, niet alleen voor mij.$B$BIk heb Magistrate Sevren verteld over je daden tegen de Agamands, en hij wil met je praten.",
  o = "Praat met Magistrate Sevren in Brill.",
  c = "Coleman is positief over je, $N. Hij vertelt over je succesvolle tochten naar de Agamand Mills.$B$BDe Forsaken hebben je talenten weer nodig...",
  g = { {"resten", "remains (rest)"}, {"wraak", "revenge"}, {"gevaar", "threat, danger"}, {"daden", "deeds, exploits (daad)"}, {"succesvolle", "successful (succesvol)"}, {"tochten", "trips, forays (tocht)"} },
},

[362] = { en = "The Haunted Mills", tier = 1,
  t = "De spookmolens",
  d = "Devlin Agamand was de jongere van de twee zonen in de familie Agamand. Toen ze leefden, waren de twee heel verschillend. Thurman was lang en vriendelijk. Zijn jongere broer was zwak en had een scherpe tong.$B$BToen Agamand Mills door de Pest viel, verbaasde het me niet dat Devlin snel bezweek. Bij de weg naar de Agamand Mills hoor je nog steeds zijn gekke gebrabbel.$B$BIk verzamel de resten van de Agamands, en ik wil die arme Devlin. Zoek hem, vernietig hem, en breng me zijn botten.",
  o = "Dood Devlin Agamand, en breng Devlin's Remains naar Coleman Farthing in Brill.",
  p = "Heb je Devlin gevonden?",
  c = "Dank je. Devlins botten staan mooi op mijn schoorsteenmantel.$B$BAls mijn koude hart nog warmte kan vinden, dan komt dat door dit: de Agamands zijn vernietigd. Ze lieten mij en mijn familie in de steek toen de Pest kwam. Nu zweer ik dat ik hun resten onder mijn hiel kapot zal trappen!",
  g = { {"spookmolens", "haunted mills (spookmolen)"}, {"verschillend", "different"}, {"scherpe tong", "sharp tongue"}, {"bezweek", "succumbed (bezwijken)"}, {"gebrabbel", "chattering, babbling"}, {"schoorsteenmantel", "mantel(piece)"}, {"lieten ... in de steek", "failed, abandoned (in de steek laten)"}, {"zweer", "swear (zweren)"}, {"hiel", "heel"}, {"kapot zal trappen", "will smash (kapot trappen)"}, {"verbaasde", "surprised (verbazen)"} },
},

[371] = { en = "At War With The Scarlet Crusade", tier = 1,
  t = "In oorlog met de Scarlet Crusade",
  d = "We zijn nog steeds in oorlog, en de Scarlet Crusade wordt sterker. Executor Arren heeft me een verslag gestuurd. Daarin staat dat Scarlet Crusaders aanvallen doen vanuit de verwoeste toren in het zuidoosten van Tirisfal, bij de Balnir Farmstead. Captain Vachon heeft daar de leiding.$b$bDood Vachon, samen met 5 Scarlet Friars. Dat wordt een zware klap voor de Crusade!",
  o = "Executor Zygand in Brill heeft je de opdracht gegeven om Captain Vachon en 5 Scarlet Friars te doden.",
  p = "Ik zie dat je terug bent, maar je taak is niet klaar. Vind je het misschien goed dat gewone mensen het plan van de Dark Lady verstoren? Of luister je misschien naar de roep van de plicht, en dood je Captain Vachon en zijn groep Scarlet Friars!",
  c = "De dood van Captain Vachon zal de opmars van de Scarlet Crusade in Tirisfal flink vertragen. Maar er dreigen andere gevaren.",
  g = { {"Daarin staat", "it says in there"}, {"de leiding", "command, the lead"}, {"zware klap", "heavy blow"}, {"opdracht", "assignment, commission"}, {"verstoren", "to disturb, to interfere with"}, {"roep", "call"}, {"opmars", "advance"}, {"flink", "considerably, quite a bit"}, {"vertragen", "to slow down"}, {"dreigen", "loom, threaten"} },
},

[445] = { en = "Delivery to Silverpine Forest", tier = 1,
  t = "Een levering voor Silverpine Forest",
  d = "Tijd is een luxe. Wie voor Lady Sylvanas werkt, heeft die luxe niet. Dat weet je nu vast wel.$b$bIk ben lid van de Royal Apothecary Society. Daarom is het mijn plicht om mijn kennis met mijn collega's te delen. Zo kunnen we samen de Dark Lady op een dag de nieuwe pest geven die ze zo graag wil.$b$bBreng deze resultaten naar Apothecary Renferrel. Hij werkt in The Sepulcher in Silverpine Forest. Volg de wegen vanuit Brill naar het zuiden. Vanuit de Undercity ga je naar het zuidwesten.",
  o = "Breng de resultaten van Apothecary Johaan naar Apothecary Renferrel in Silverpine Forest.",
  p = "Wat wil je van mij, $c?",
  c = "Ah, wat aardig van Apothecary Johaan om zijn onderzoek te sturen. Er gebeurt hier in Silverpine zoveel nieuws dat ik de resultaten uit Lordaeron en Tirisfal Glades bijna vergeten was. Dat doet me eraan denken: ik moet die stalen snel naar de Necropolis sturen.$b$bMaar sorry dat ik zo doorpraat. Blijf wat langer in Silverpine, $N. We kunnen hier wel een sterke $c zoals jij gebruiken.",
  g = { {"levering", "delivery"}, {"luxe", "luxury"}, {"lid", "member"}, {"kennis", "knowledge"}, {"delen", "to share"}, {"resultaten", "findings, results (resultaat)"}, {"onderzoek", "research"}, {"Dat doet me eraan denken", "that reminds me"}, {"stalen", "samples (staal)"}, {"doorpraat", "ramble on (doorpraten)"} },
},

[354] = { en = "Deaths in the Family", tier = 1,
  t = "Doden in de familie",
  d = "De familie Agamand was de rijkste familie van Tirisfal Glades. Ik werkte vroeger in hun molens... voor de Pest.$B$BToen de Scourge voor het eerst kwam, versterkten de Agamands hun huis. Ze overtuigden hun personeel om te blijven en te helpen met de verdediging. We waren dwazen, maar we waren tenminste trouwe dwazen.$B$BDe Agamands waren trots, en door hun trots zijn wij nu ondood. En nu zijn ze dienaren van de Scourge!$B$BDien de Forsaken: versla de Agamands, die door de Pest gevallen zijn. Dien mij: breng me hun resten.",
  o = "Breng Gregor's Remains, Nissa's Remains en Thurman's Remains naar Coleman Farthing in Brill.",
  p = "Heb je de resten van de Agamands? Zijn die vervloekte beesten eindelijk vernietigd?",
  c = "Wraak smaakt zoet, vind je niet? Toen je de Agamands vernietigde, merkte je toen nog iets van een vrije wil in ze? Ik hoop het. Ik hoop dat ze angst voelden, voordat ze tot niets werden geslagen.$B$BHet is een dwaze hoop, dat weet ik. Maar ik koester die hoop toch.",
  g = { {"rijkste", "most prosperous, richest (rijk)"}, {"versterkten", "fortified (versterken)"}, {"overtuigden", "convinced (overtuigen)"}, {"personeel", "staff, employees"}, {"verdediging", "defense"}, {"trots", "pride; proud"}, {"versla", "defeat (verslaan)"}, {"smaakt", "tastes (smaken)"}, {"vrije wil", "free will"}, {"angst", "fear"}, {"tot niets werden geslagen", "were smashed into oblivion"}, {"koester", "cherish, foster (koesteren)"} },
},

[356] = { en = "Rear Guard Patrol", tier = 1,
  t = "Patrouille van de achterhoede",
  d = "De verdedigers op The Bulwark beschermen Tirisfal tegen de Plaguelands. Ze zijn altijd alert. Maar soms glipt er Scourge langs hen.$B$BOns succes bij de Bulwark hangt af van een gevecht aan één front. We kunnen geen aanval van achteren toestaan. En de aanvoer van onze verdedigers mag niet worden afgesneden.$B$BHelp de Bulwark. Patrouilleer naar het oosten en dood alle Scourge die je vindt. Doe vooral je best bij de Balnir Farmstead, in het oosten. Het is een veilige plek geworden voor Scourge die hier niet horen.",
  o = "Dood 8 Bleeding Horrors en 8 Wandering Spirits. Ga dan terug naar Linnea in haar kamp.",
  p = "Heb je een verslag van je patrouille?",
  c = "Heel goed. Door jouw werk houden we de Scourge op afstand. Ik stuur een eervolle vermelding naar mijn meerdere, Executor Zygand.",
  g = { {"achterhoede", "rear guard"}, {"hangt af van", "depends on (afhangen van)"}, {"van achteren", "from the rear"}, {"toestaan", "to allow"}, {"aanvoer", "supply line, supplies"}, {"afgesneden", "cut off (afsnijden)"}, {"Patrouilleer", "patrol (patrouilleren)"}, {"Doe ... je best", "make an effort (je best doen)"}, {"op afstand", "at bay, at a distance"}, {"eervolle vermelding", "commendation"}, {"meerdere", "superior"} },
},

[369] = { en = "A New Plague", tier = 1,
  t = "Een nieuwe pest",
  d = "Terwijl jij aan het verzamelen was, vond ik een oude tekst in een van mijn boeken. Daarin staat dat een eeuwenoude pest duizenden onschuldige slachtoffers doodde. Later ontdekte men dat de dodelijke stof van die pest bewaard bleef in het gif van Night Web Spiders.$b$bBreng me wat gif van een Vicious Night Web Spider, zodat ik dit experiment kan afmaken. Ik wil zien of het besmettelijke deel van het gif werkt met mijn nieuwe brouwsel. Volgens de geruchten vind je de spinnen in het oosten van Tirisfal Glades.",
  o = "Apothecary Johaan in het dorp Brill wil dat je hem 4 stalen gif brengt van een Vicious Night Web Spider.",
  p = "Heb je al wat gif van een Vicious Night Web Spider, $N? Het is het laatste onderdeel dat ik nodig heb om mijn experiment te testen.",
  c = "Ah, dit gif is perfect, $N. Al het andere zit al in mijn brouwsel en is ingekookt. Eindelijk kan ik deze nieuwe dodelijke stof proberen!",
  g = { {"eeuwenoude", "ancient (eeuwenoud)"}, {"onschuldige", "innocent (onschuldig)"}, {"ontdekte men", "it was discovered (ontdekken)"}, {"stof", "substance, agent"}, {"bewaard bleef", "was preserved (bewaren)"}, {"gif", "venom, poison"}, {"afmaken", "to finish"}, {"besmettelijke", "contagious (besmettelijk)"}, {"geruchten", "rumors (gerucht)"}, {"onderdeel", "component, part"}, {"ingekookt", "boiled down (inkoken)"} },
},

[492] = { en = "A New Plague", tier = 1,
  t = "Een nieuwe pest",
  d = "Volgens de Deathguard is er weer zo'n dwaze Dwarven Mountaineer gevangen. De Deathguard gebruikt de kelder van de Gallows End Tavern graag als cel. Daar blijven gevangenen tot ze 'goed' behandeld kunnen worden.$b$bWaarom ga je niet even kijken hoe de Captured Mountaineer dit speciale drankje bevalt? Ik heb het voor hem gemaakt. Er zit een klein voorproefje in van wat de Dark Lady van plan is met de rest van Azeroth.",
  o = "Breng Johaan's Special Drink naar de Captured Mountaineer.",
  p = "Als ik mijn trouwe geweer had, was je al zo goed als dood, $C. Wacht maar tot de Steam Tank Brigade komt om me te redden!",
  c = "Ah, eindelijk iets te drinken. Het is vast geen Rhapsody Malt, maar ik neem nu alles om mijn keel te smeren.",
  g = { {"gevangen", "captured (vangen)"}, {"cel", "holding cell"}, {"gevangenen", "prisoners (gevangene)"}, {"behandeld", "dealt with (behandelen)"}, {"bevalt", "pleases, is liked (bevallen)"}, {"voorproefje", "foretaste, hint"}, {"van plan", "planning"}, {"geweer", "rifle"}, {"zo goed als", "as good as"}, {"redden", "to rescue"}, {"mijn keel te smeren", "to wet my whistle (de keel smeren)"} },
},

[372] = { en = "At War With The Scarlet Crusade", tier = 1,
  t = "In oorlog met de Scarlet Crusade",
  d = "Scarlet Crusaders doen aanvallen vanuit de verwoeste toren in het noorden van Tirisfal, voorbij Faol's Rest. Volgens onze informatie is een wrede commandant de baas over deze slechte groep. Hij heet Captain Melrache.$b$bIk geef je nu een speciale en gevaarlijke missie. Dood Melrache en zijn twee lijfwachten, in de naam van de Dark Lady.",
  o = "Executor Zygand in het dorp Brill wil dat je Captain Melrache en zijn twee lijfwachten vermoordt.",
  p = "Je hebt je plicht nog niet gedaan, $c. We kunnen het plan van de Dark Lady niet uitvoeren als de Scarlet Crusade onze soldaten lastigvalt. Zorg dat ze sterven en doe je plicht voor Sylvanas!",
  c = "Je hebt het heel goed gedaan, $c. Met wrede vechters zoals jij, die veroveren in de naam van de Forsaken, is ons ras een stap dichter bij de overwinning op Arthas, voor eens en altijd. Ik heb een goed gevoel over je, kameraad.",
  g = { {"wrede", "ruthless, cruel (wreed)"}, {"commandant", "commander"}, {"de baas over", "in charge of"}, {"lijfwachten", "bodyguards (lijfwacht)"}, {"vermoordt", "assassinate, murder (vermoorden)"}, {"uitvoeren", "to carry out"}, {"lastigvalt", "pesters, harasses (lastigvallen)"}, {"veroveren", "to conquer"}, {"overwinning", "victory"}, {"voor eens en altijd", "once and for all"}, {"kameraad", "comrade"} },
},

[409] = { en = "Proving Allegiance", tier = 1,
  t = "Bewijs van trouw",
  d = "Je zegt dat je niet gebonden bent aan de wil van de Lich King. De betovering die Bethor op mijn boek legde, bevestigt dat. Maar voordat ik je geloof, wil ik bewijs dat je een vijand van de Scourge bent.$B$BVlak voor de zuidkust van dit eiland staat een oud, bebloed altaar. Het wordt gebruikt door een machtige agent van de Scourge: Lillith Nefara.$B$BPak een Candle of Beckoning uit deze kist hier. Steek die aan op het altaar, en Lillith wordt wakker. Vernietig Lillith, dan geloof ik dat je een vijand van de Lich King bent.",
  o = "Haal een Candle of Beckoning.$B$BRoep Lillith Nefara op en dood haar.$B$BGa terug naar Gunther op zijn eiland.",
  p = "Ik wacht op bewijs van je trouw, $c.",
  c = "Je hebt Lillith Nefara verslagen. Dat bewijst dat je een vijand van de Scourge bent. Ongelooflijk.$B$BIk dacht dat ik de enige ondode was met een vrije wil. Maar jij laat me zien dat er anderen zijn die de macht van de Lich King hebben gebroken.",
  g = { {"trouw", "allegiance, loyalty"}, {"gebonden", "bound (binden)"}, {"bevestigt", "corroborates, confirms (bevestigen)"}, {"Vlak voor", "just off, right in front of"}, {"zuidkust", "southern coast"}, {"bebloed", "bloody"}, {"altaar", "altar"}, {"kist", "crate, chest"}, {"Steek die aan", "light it (aansteken)"}, {"Roep ... op", "summon (oproepen)"}, {"verslagen", "defeated (verslaan)"}, {"Ongelooflijk", "incredible"}, {"gebroken", "broken (breken)"} },
},

[411] = { en = "The Prodigal Lich Returns", tier = 1,
  t = "De verloren lich keert terug",
  d = "Breng deze Nether Gem naar mijn oude kameraad Bethor. Daarmee kunnen we met elkaar praten... en ik heb hem veel te vertellen.",
  o = "Breng de Nether Gem naar Bethor Iceshard in de Undercity.",
  p = "Heb je Gunthers boek teruggebracht? Heeft hij geantwoord?",
  c = "Je hebt hem overgehaald om zich bij ons aan te sluiten! Je hebt iets groots gedaan voor de Forsaken, $N. De Dark Lady zal het horen.",
  g = { {"keert terug", "returns (terugkeren)"}, {"kameraad", "comrade"}, {"Daarmee", "with it"}, {"teruggebracht", "returned (terugbrengen)"}, {"geantwoord", "responded (antwoorden)"}, {"overgehaald", "convinced (overhalen)"}, {"zich bij ons aan te sluiten", "to join us (zich aansluiten)"}, {"iets groots", "something great, a great deed"} },
},

})

